('Company Letterhead','2026-05-15 15:21:48.255627','2026-07-12 21:11:44.765083','Administrator','Administrator',0,0,'Company Letterhead','DocType','HTML','Image','Yes','Accounts',0,0,'Left',NULL,0.000000000,0.000000000,'Left',NULL,0.000000000,0.000000000,'<table class=\"invoice-header\">\n	<tbody>\n		<tr>\n			<td class=\"logo-cell\" style=\"vertical-align:middle ! important\">\n				<div class=\"logo-container\">\n					{% set company_logo = frappe.db.get_value(\"Company\", doc.company, \"company_logo\") if doc.get(\"company\") else None %} {% if\n					company_logo %}\n					<img src=\"{{ frappe.utils.get_url(company_logo) }}\" alt=\"Company Logo\">\n					{% endif %}\n				</div>\n			</td>\n\n			<td class=\"company-details\">\n				{% if doc.company %}<div class=\"company-name\">{{ doc.company }}</div>{% endif %}\n				{% if doc.company_address %} {% set company_address = frappe.db.get_value(\"Address\",\n				doc.company_address, [\"address_line1\", \"address_line2\", \"city\", \"state\", \"pincode\",\n				\"country\"], as_dict=True) %} {% elif doc.billing_address %} {% set company_address =\n				frappe.db.get_value(\"Address\", doc.billing_address, [\"address_line1\", \"address_line2\", \"city\",\n				\"state\", \"pincode\", \"country\"], as_dict=True) %} {% endif %} {% if company_address %} {{\n				company_address.address_line1 or \"\" }}<br>\n				{% if company_address.address_line2 %} {{ company_address.address_line2 }}<br>\n				{% endif %} {{ company_address.city or \"\" }}, {{ company_address.state or \"\" }} {{\n				company_address.pincode or \"\" }}, {{ company_address.country or \"\"}}<br>\n				{% endif %}\n			</td>\n\n			<td class=\"invoice-info-cell\">\n				{% set website = frappe.db.get_value(\"Company\", doc.company, \"website\") if doc.get(\"company\") else None %} {% set email =\n				frappe.db.get_value(\"Company\", doc.company, \"email\") if doc.get(\"company\") else None %} {% set phone_no =\n				frappe.db.get_value(\"Company\", doc.company, \"phone_no\") if doc.get(\"company\") else None %}\n\n				<div class=\"invoice-info\">\n					<span class=\"invoice-label\">{{ doc.doctype }}</span>\n					<span>{{ doc.name }}</span>\n				</div>\n				{% if website %}\n				<div class=\"invoice-info\">\n					<span class=\"invoice-label\">{{ _(\"Website:\") }}</span>\n					<span>{{ website }}</span>\n				</div>\n				{% endif %} {% if email %}\n				<div class=\"invoice-info\">\n					<span class=\"invoice-label\">{{ _(\"Email:\") }}</span>\n					<span>{{ email }}</span>\n				</div>\n				{% endif %} {% if phone_no %}\n				<div class=\"invoice-info\">\n					<span class=\"invoice-label\">{{ _(\"Contact:\") }}</span>\n					<span>{{ phone_no }}</span>\n				</div>\n				{% endif %}\n			</td>\n		</tr>\n	</tbody>\n</table>','	.letter-head {\n		border-radius: 18px;\n		padding-right: 12px;\n		margin-left: 12px;\n		margin-right: 12px;\n	}\n\n	.letter-head td {\n		padding: 0px !important;\n	}\n	.invoice-header {\n		width: 100%;\n	}\n	.logo-cell {\n		width: 100px;\n		text-align: center;\n		position: relative;\n	}\n	.logo-container {\n		width: 90px;\n		display: block;\n	}\n	.logo-container img {\n		max-width: 90px;\n		max-height: 90px;\n		display: inline-block;\n		border-radius: 15px;\n	}\n	.company-details {\n		width: 40%;\n		align-content: center;\n	}\n	.company-name {\n		font-size: 14px;\n		font-weight: bold;\n		color: #171717;\n		margin-bottom: 4px;\n	}\n	.invoice-info-cell {\n		float: right;\n		vertical-align: top;\n	}\n	.invoice-info {\n		margin-bottom: 2px;\n	}\n	.invoice-label {\n		color: #7c7c7c;\n		display: inline-block;\n		margin-right: 5px;\n	}',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Company Letterhead - Grey','2026-05-15 15:21:48.373815','2026-07-12 22:03:24.525672','Administrator','Administrator',0,0,'Company Letterhead - Grey','DocType','HTML','Image','Yes','Accounts',0,0,'Left',NULL,0.000000000,0.000000000,'Left',NULL,0.000000000,0.000000000,'<table class=\"letterhead-container\" style=\"width:100%\">\n	<tbody>\n		<tr>\n			<td class=\"logo-address\">\n				{% set company_logo = frappe.db.get_value(\"Company\", doc.company, \"company_logo\") if doc.get(\"company\") else None %} {% if\n				company_logo %}\n				<div class=\"logo\">\n					<img src=\"{{ frappe.utils.get_url(company_logo) }}\" style=\"width:200px\">\n				</div>\n				{% endif %}\n				{% if doc.company %}<div class=\"company-name\">{{ doc.company }}</div>{% endif %}\n				<div class=\"company-address\">\n					{% if doc.company_address %} {% set company_address = frappe.db.get_value(\"Address\",\n					doc.company_address, [\"address_line1\", \"address_line2\", \"city\", \"state\", \"pincode\",\n					\"country\"], as_dict=True) %} {% elif doc.billing_address %} {% set company_address =\n					frappe.db.get_value(\"Address\", doc.billing_address, [\"address_line1\", \"address_line2\",\n					\"city\", \"state\", \"pincode\", \"country\"], as_dict=True) %} {% endif %} {% if company_address\n					%} {{ company_address.address_line1 or \"\" }}<br>\n					{% if company_address.address_line2 %} {{ company_address.address_line2 }}<br>\n					{% endif %} {{ company_address.city or \"\" }}, {{ company_address.state or \"\" }} {{\n					company_address.pincode or \"\" }}, {{ company_address.country or \"\"}}<br>\n					{% endif %}\n				</div>\n			</td>\n\n			<td style=\"vertical-align:top\">\n				<div style=\"height:90px;margin-bottom:10px;text-align:right\">\n					<div class=\"invoice-title\">{{ doc.doctype }}</div>\n					<div class=\"invoice-number\">{{ doc.name }}</div>\n					<br>\n				</div>\n				<div style=\"text-align:left;float:right\" class=\"other-details\">\n					{% if doc.company %}{% set company_details = frappe.db.get_value(\"Company\", doc.company, [\"website\", \"email\",\n					\"phone_no\"], as_dict=True) %}{% set website = company_details.website %}{% set email =\n					company_details.email %}{% set phone_no = company_details.phone_no %}{% else %}{% set website = None %}{% set email = None %}{% set phone_no = None %}{% endif %} {% if website %}\n					<div>\n						<span class=\"contact-title\">{{ _(\"Website:\") }}</span><span class=\"contact-value\">{{ website }}</span>\n					</div>\n					{% endif %} {% if email %}\n					<div>\n						<span class=\"contact-title\">{{ _(\"Email:\") }}</span><span class=\"contact-value\">{{ email }}</span>\n					</div>\n					{% endif %} {% if phone_no %}\n					<div>\n						<span class=\"contact-title\">{{ _(\"Contact:\") }}</span><span class=\"contact-value\">{{ phone_no }}</span>\n					</div>\n					{% endif %}\n				</div>\n			</td>\n		</tr>\n	</tbody>\n</table>\n','	.print-format-preview {\n		margin-top: 12px;\n	}\n	.letter-head {\n		border-radius: 18px;\n		background: #f8f8f8;\n		padding: 12px;\n		margin-left: 12px;\n		margin-right: 12px;\n	}\n	.letterhead-container {\n		width: 100%;\n	}\n	.letterhead-container .other-details {\n		position: absolute;\n		right: 0;\n		bottom: 0;\n	}\n	.logo-address {\n		width: 65%;\n		vertical-align: top;\n	}\n\n	.letter-head .logo {\n		width: 90px;\n		display: block;\n		margin-bottom: 10px;\n	}\n\n	.letter-head .logo img {\n		border-radius: 15px;\n	}\n\n	.company-name {\n		color: #171717;\n		font-weight: bold;\n		line-height: 23px;\n		margin-bottom: 5px;\n	}\n\n	.company-address {\n		color: #171717;\n		width: 300px;\n	}\n\n	.invoice-title {\n		font-weight: bold;\n	}\n\n	.invoice-number {\n		color: #7c7c7c;\n	}\n\n	.contact-title {\n		color: #7c7c7c;\n		width: 60px;\n		display: inline-block;\n		vertical-align: top;\n		margin-right: 10px;\n	}\n\n	.contact-value {\n		color: #171717;\n		display: inline-block;\n	}\n	.letterhead-container td {\n		padding: 0px !important;\n		position: relative;\n	}',NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('Company Letterhead Report','2026-05-15 19:49:47.582252','2026-06-24 18:06:39.820968','Administrator','Administrator',0,0,'Company Letterhead Report','Report','HTML','Image','Yes','Accounts',0,0,'Left',NULL,0.000000000,0.000000000,'Left',NULL,0.000000000,0.000000000,'<table class=\"invoice-header\">\n	<tbody>\n		<tr>\n\n			<td class=\"logo-cell\" style=\"vertical-align:top\">\n				{% if doc.company %}{% set company = frappe.get_doc(\"Company\", doc.company) %}{% else %}{% set company = frappe._dict() %}{% endif %}\n\n				<div class=\"logo-container\">\n					{% if company.company_logo %}\n					<img src=\"{{ frappe.utils.get_url(company.company_logo) }}\" alt=\"Company Logo\">\n					{% endif %}\n				</div>\n			</td>\n\n			<td class=\"company-details\" style=\"vertical-align:top\">\n				{% if company.name %}<div class=\"company-name\">{{ company.name }}</div>{% endif %}\n\n				{% set company_address_name = frappe.db.get_value(\n					\"Dynamic Link\",\n					{\n						\"link_doctype\": \"Company\",\n						\"link_name\": company.name,\n						\"parenttype\": \"Address\"\n					},\n					\"parent\"\n				) %}\n\n				{% if company_address_name %}\n					{% set company_address = frappe.db.get_value(\n						\"Address\",\n						company_address_name,\n						[\"address_line1\", \"address_line2\", \"city\", \"state\", \"pincode\", \"country\"],\n						as_dict=True\n					) %}\n				{% endif %}\n\n				{% if company_address %}\n				<div class=\"company-address\">\n					{{ company_address.address_line1 or \"\" }}\n\n					{% if company_address.address_line2 %}\n						<br>{{ company_address.address_line2 }}\n					{% endif %}\n\n					<br>\n\n					{{ company_address.city or \"\" }}\n					{% if company_address.state %}, {{ company_address.state }}{% endif %}\n					{{ company_address.pincode or \"\" }}\n\n					{% if company_address.country %}\n						, {{ company_address.country }}\n					{% endif %}\n				</div>\n				{% endif %}\n			</td>\n\n			<td class=\"invoice-info-cell\" style=\"vertical-align:top;text-align:right\">\n\n				{% set website = frappe.db.get_value(\"Company\", doc.company, \"website\") %}\n				{% set email = frappe.db.get_value(\"Company\", doc.company, \"email\") %}\n				{% set phone_no = frappe.db.get_value(\"Company\", doc.company, \"phone_no\") %}\n\n				{% if website %}\n				<div class=\"invoice-info\">\n					<span class=\"invoice-label\">{{ _(\"Website:\") }}</span>\n					<span>{{ website }}</span>\n				</div>\n				{% endif %}\n\n				{% if email %}\n				<div class=\"invoice-info\">\n					<span class=\"invoice-label\">{{ _(\"Email:\") }}</span>\n					<span>{{ email }}</span>\n				</div>\n				{% endif %}\n\n				{% if phone_no %}\n				<div class=\"invoice-info\">\n					<span class=\"invoice-label\">{{ _(\"Contact:\") }}</span>\n					<span>{{ phone_no }}</span>\n				</div>\n				{% endif %}\n			</td>\n\n		</tr>\n	</tbody>\n</table>','.letter-head {\n	border-radius: 18px;\n	padding: 8px 10px;\n	margin: 10px 0 14px;\n	font-family: Inter, sans-serif;\n	font-size: 14px;\n	color: #171717;\n}\n\n.letter-head td {\n	padding: 0 !important;\n	vertical-align: middle;\n}\n\n.invoice-header {\n	width: 100%;\n	border-collapse: collapse;\n	table-layout: fixed;\n	border-bottom: 1px solid #ededed;\n	padding-bottom: 10px;\n}\n\n.logo-cell {\n	width: 100px;\n	text-align: center;\n	white-space: nowrap;\n}\n\n.logo-container {\n	display: inline-block;\n	margin: auto;\n}\n\n.logo-container img {\n	max-width: 95px;\n	max-height: 95px;\n	display: block;\n	border-radius: 12px;\n}\n\n.company-details {\n	width: 55%;\n	padding-left: 10px !important;\n	line-height: 1.5;\n}\n\n.company-name {\n	font-size: 14px;\n	font-weight: 600;\n	color: #171717;\n	margin-bottom: 4px;\n}\n\n.company-address {\n	font-size: 14px;\n	line-height: 1.5;\n	color: #171717;\n}\n\n.invoice-info-cell {\n	width: 240px;\n	text-align: right;\n	vertical-align: top !important;\n	line-height: 1.5;\n}\n\n.document-name {\n	font-size: 14px;\n	font-weight: 600;\n	color: #171717;\n	margin-bottom: 6px;\n}\n\n.invoice-info {\n	font-size: 14px;\n	color: #171717;\n	margin-bottom: 2px;\n	font-variant-numeric: tabular-nums;\n}\n\n.invoice-label {\n	color: #7c7c7c;\n	font-weight: 500;\n	margin-right: 4px;\n	display: inline-block;\n}',NULL,NULL,NULL,NULL,NULL,NULL,NULL);
