  `source_name` varchar(140) DEFAULT NULL,
  `app` varchar(140) DEFAULT NULL,
  `link` text DEFAULT NULL,
  `for_user` varchar(140) DEFAULT NULL,
  `from_user` varchar(140) DEFAULT NULL,
